```sql
/* Выбираем заведения с форматом обслуживания "buffet" или "coffee shop", */
/* которые открыты в интервале с 07:30 до 16:00 */
SELECT
    r."id",
    r."name",
    r."address",
    r."service_format",
    r."hours"
FROM "restaurant" AS r
WHERE LOWER(r."service_format") IN ('buffet', 'coffee shop')
  /* Проверяем, что время открытия не позже 07:30 и время закрытия не раньше 16:00 */
  AND (
      /* Извлекаем время открытия и закрытия из текстового поля hours */
      SPLIT_PART(r."hours", '-', 1)::time <= TIME '07:30'
      AND SPLIT_PART(r."hours", '-', 2)::time >= TIME '16:00'
  )
ORDER BY r."service_format", r."name";
```

